export const ORDER_STATUSES = [
"pending", "paid", "shipped", "on_hold",
] as const;

export const orderStatuses = {
...
on_hold: { label: "On hold", tone: "warning",
next: ["paid", "cancelled"] },
} satisfies Record<string, StatusRule>;

export const statusLabels = {
...
on_hold: "On hold",
};

function toneOf(status: OrderStatus) {
...
case "on_hold": return "warning";
}

export const allowedNext = {
...
on_hold: ["paid", "cancelled"],
};

const label = statusLabels[status];
const tone = toneOf(status);
return <Badge tone={tone}>{label}</Badge>;

if (!allowedNext[order.status].includes(to)) {
throw new InvalidTransitionError(order.status, to);
}

if (!orderStatuses[order.status].next.includes(to)) {
throw new InvalidTransitionError(order.status, to);
}
